package app.noir.mobile;
import android.app.*;
import android.content.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import org.junit.*;
import java.util.*;
import static org.junit.Assert.*;
public final class WatchChoiceTest {
 AuditPhoneFixture f;MainActivity a;Instrumentation.ActivityMonitor player;String choice;
 @Before public void setup()throws Exception{f=new AuditPhoneFixture();BackgroundSync.device(f.data.context).edit().putBoolean("askedBattery",true).apply();WatchChoice.preference(f.data.context,"");player=f.test.addMonitor(PlayerActivity.class.getName(),null,true);a=f.launch(MainActivity.class);}
 @After public void cleanup()throws Exception{f.ui(()->{NoirSheet s=WatchChoice.sheets.get(a);if(s!=null)s.dismiss();});f.test.removeMonitor(player);f.close();}
 JSONObject item(String id,boolean available)throws Exception{return f.data.rememberPhoneItem(new JSONObject().put("id",id).put("group",id).put("title","Choice show").put("imdb","tt123").put("season",2).put("episode",5).put("airsAt","2020-01-01T00:00:00Z").put("inLibrary",true).put("available",available));}
 View row(NoirSheet s,String label){View v=AuditPhoneFixture.find(s.body,x->label.equals(x.getTag()));assertNotNull(label,v);return v;}
 void assertRows(NoirSheet s){assertNotNull(s);assertTrue(s.dialog.isShowing());assertEquals("noir-sheet",s.root.getTag());String[] labels={"Play from your PC","Stream now","Choose a stream…","Save to this phone","Keep this show ready"};for(int n=0;n<labels.length;n++)assertEquals(labels[n],s.body.getChildAt(n).getTag());}
 void paired()throws Exception{f.data.rememberPeer("127.0.0.1:49272",new String(new char[64]).replace('\0','A'),new String(new char[64]).replace('\0','B'));assertTrue(f.data.paired());f.data.profiles.link(f.data.profileId,"default","Fixture","#E4C084","fixture-host");f.data.fetchOverride=(path,body)->{if(path.equals("/v1/changes"))return new JSONObject().put("revision","r1").put("profile","default");return new JSONObject().put("acknowledged",new JSONArray()).put("revision","r1").put("library",new JSONObject().put("profileId","default").put("profileName","Fixture").put("profileColor","#E4C084").put("hostId","fixture-host").put("serverTime",System.currentTimeMillis()).put("items",f.data.items()));};f.data.online=true;}
 @Test public void missingDetailHeroAndContinueUseOrderedSheetWithoutStreamingSource()throws Exception{JSONObject item=item("missing",false);f.ui(()->{a.open(item);View hero=AuditPhoneFixture.find(a.body,v->v instanceof TextView&&((TextView)v).getText().toString().contains("▶ Play")&&v.hasOnClickListeners());assertNotNull("Missing detail hero action",hero);hero.performClick();NoirSheet s=WatchChoice.sheets.get(a);assertRows(s);assertTrue(row(s,"Play from your PC").getContentDescription().toString().contains("Pair with your PC first"));assertEquals(.45f,row(s,"Stream now").getAlpha(),.001f);assertTrue(row(s,"Stream now").getContentDescription().toString().contains("No streaming source set up"));assertTrue(row(s,"Stream now").isFocusable());s.dismiss();a.detail="";NoirUi.Next next=new NoirUi.Next(item,NoirUi.MISSING,System.currentTimeMillis(),0);View card=a.ui.continueCard(next);View play=((ViewGroup)card).getChildAt(0);assertTrue(play.hasOnClickListeners());play.performClick();assertRows(WatchChoice.sheets.get(a));});assertEquals(0,player.getHits());}
 @Test public void pcCopyChoiceRemembersAndPlaybackSettingsResets()throws Exception{JSONObject item=item("pc-copy",true);paired();f.ui(()->{WatchChoice.open(a,item,false);NoirSheet s=WatchChoice.sheets.get(a);assertRows(s);assertEquals(1f,row(s,"Play from your PC").getAlpha(),.001f);((CheckBox)s.body.getChildAt(s.body.getChildCount()-1)).setChecked(true);row(s,"Play from your PC").performClick();assertEquals("pc",WatchChoice.preference(f.data.context));});f.until(()->player.getHits()>=1);int first=player.getHits();f.ui(()->{WatchChoice.open(a,item,false);assertNull(WatchChoice.sheets.get(a));});f.until(()->player.getHits()>first);f.ui(()->{NoirSheet settings=WatchChoice.settings(a);row(settings,"Ask every time").performClick();assertEquals("",WatchChoice.preference(f.data.context));WatchChoice.open(a,item,false);assertRows(WatchChoice.sheets.get(a));});}
 @Test public void startOverSurvivesTheStreamChoice()throws Exception{JSONObject item=new JSONObject().put("id","restart-1");JSONObject marked=WatchChoice.streamItem(item,true);assertTrue(marked.optBoolean("noirRestart"));assertFalse("the caller's item is not changed",item.has("noirRestart"));assertSame(item,WatchChoice.streamItem(item,false));}
 @Test public void localCopyBypassesSheetAndArabicSheetIsRtl()throws Exception{JSONObject item=item("local",false);f.data.localFile("local","content://app.noir.mobile/fixture");f.ui(()->{a.play(item,false);assertNull(WatchChoice.sheets.get(a));});assertEquals(1,player.getHits());f.data.localFile("local","");f.ui(()->{Loc.arabic=true;WatchChoice.open(a,item,false);NoirSheet s=WatchChoice.sheets.get(a);assertRows(s);assertEquals(View.LAYOUT_DIRECTION_RTL,s.root.getLayoutDirection());assertTrue(row(s,"Stream now").getContentDescription().toString().contains(Loc.t("No streaming source set up")));assertNotEquals("How do you want to watch?",Loc.t("How do you want to watch?"));});}
 @Test public void offlinePcGetsFreshProbeAndUnavailableDefaultReturnsToSheet()throws Exception{JSONObject item=item("pc-probe",true);paired();f.data.online=false;f.ui(()->WatchChoice.open(a,item,false));f.until(()->WatchChoice.sheets.get(a)!=null);f.ui(()->{NoirSheet s=WatchChoice.sheets.get(a);assertEquals(1f,row(s,"Play from your PC").getAlpha(),.001f);s.dismiss();});WatchChoice.preference(f.data.context,"pc");f.data.online=false;f.data.fetchOverride=(path,body)->{throw new java.io.IOException("offline fixture");};f.ui(()->WatchChoice.open(a,item,false));f.until(()->WatchChoice.sheets.get(a)!=null);f.ui(()->{NoirSheet s=WatchChoice.sheets.get(a);assertTrue(row(s,"Play from your PC").getContentDescription().toString().contains("Your PC isn't reachable right now"));assertEquals(.45f,row(s,"Play from your PC").getAlpha(),.001f);});}
}
